// Per-store Media Library: file storage (local disk, under
// public/uploads/store-<id>/, served statically by server.js's existing
// `express.static(public/)`) plus the pz_media table that's every
// consumer's actual source of truth for a file's URL, size and name.
//
// Every uploaded file's on-disk name is generated by US (see safeFilename
// below) — never derived from whatever the browser sent as the original
// filename beyond its extension. That's what makes store-scoping safe:
// nothing here ever builds a path from user input, so there's no path-
// traversal surface despite files living in a directory named after
// req.store.id.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const multer = require('multer');
const { pool, TABLES } = require('../db/database');

const UPLOAD_ROOT = path.join(__dirname, '..', 'public', 'uploads');

// Images cover most uses (products, logos, gallery/text+image); PDF covers
// the common "downloadable spec sheet / size chart" case; MP4/WEBM cover
// the hero section's background-video field — without opening this up to
// arbitrary file types.
const ALLOWED_MIME_TYPES = new Set([
  'image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/svg+xml',
  'application/pdf',
  'video/mp4', 'video/webm',
]);
const EXT_BY_MIME = {
  'image/jpeg': '.jpg',
  'image/png': '.png',
  'image/webp': '.webp',
  'image/gif': '.gif',
  'image/svg+xml': '.svg',
  'application/pdf': '.pdf',
  'video/mp4': '.mp4',
  'video/webm': '.webm',
};
// One shared ceiling for every file type. 15MB was fine for images/PDFs
// alone, but a hero background video — even a short, well-compressed loop —
// routinely runs larger, so this now covers both.
const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB/file
const MAX_FILES_PER_UPLOAD = 10;

function storeUploadDir(storeId) {
  return path.join(UPLOAD_ROOT, `store-${storeId}`);
}

// Takes only the EXTENSION from the browser-supplied name (lowercased,
// alnum-only, capped) — everything else about the saved filename is ours.
// Falls back to a mime-type-derived extension when the original name had
// none or an unusable one (e.g. a camera's IMG_20240101 with no suffix).
function safeExt(originalName, mimeType) {
  const ext = path.extname(String(originalName || '')).toLowerCase().replace(/[^a-z0-9.]/g, '');
  if (ext && ext.length >= 2 && ext.length <= 10) return ext;
  return EXT_BY_MIME[mimeType] || '';
}

const storage = multer.diskStorage({
  destination(req, file, cb) {
    if (!req.store || !req.store.id) return cb(new Error('NO_STORE_CONTEXT'));
    const dir = storeUploadDir(req.store.id);
    fs.mkdir(dir, { recursive: true }, (err) => cb(err, dir));
  },
  filename(req, file, cb) {
    const name = `${Date.now()}-${crypto.randomBytes(8).toString('hex')}${safeExt(file.originalname, file.mimetype)}`;
    cb(null, name);
  },
});

function fileFilter(req, file, cb) {
  if (!ALLOWED_MIME_TYPES.has(file.mimetype)) {
    cb(new Error('UNSUPPORTED_FILE_TYPE'));
    return;
  }
  cb(null, true);
}

// Mounted as `upload.array('files', MAX_FILES_PER_UPLOAD)` by the route —
// exported as the configured multer instance so the route owns exactly how
// it's invoked (array vs single) rather than baking that in here.
const upload = multer({ storage, fileFilter, limits: { fileSize: MAX_FILE_SIZE, files: MAX_FILES_PER_UPLOAD } });

async function recordUpload(storeId, userId, file) {
  const url = `/uploads/store-${storeId}/${file.filename}`;
  const [result] = await pool.query(
    `INSERT INTO ${TABLES.media} (store_id, filename, original_name, mime_type, size, url, uploaded_by) VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [storeId, file.filename, String(file.originalname || file.filename).slice(0, 255), file.mimetype, file.size, url, userId || null]
  );
  const [[row]] = await pool.query(`SELECT * FROM ${TABLES.media} WHERE id = ?`, [result.insertId]);
  return row;
}

// Newest first — a merchant's most recent uploads are what they're almost
// always looking for right after uploading.
async function listMedia(storeId, { limit = 60, offset = 0 } = {}) {
  const [rows] = await pool.query(
    `SELECT * FROM ${TABLES.media} WHERE store_id = ? ORDER BY created_at DESC, id DESC LIMIT ? OFFSET ?`,
    [storeId, Math.min(Math.max(parseInt(limit, 10) || 60, 1), 200), Math.max(parseInt(offset, 10) || 0, 0)]
  );
  const [[{ total }]] = await pool.query(`SELECT COUNT(*) AS total FROM ${TABLES.media} WHERE store_id = ?`, [storeId]);
  return { rows, total };
}

// Deletes the DB row and best-effort removes the file from disk. Scoped to
// storeId in the same query that finds the row — a store can never delete
// (or even discover the existence of) another store's media by guessing an
// id, the same boundary every other per-store resource in this app has.
async function deleteMedia(storeId, mediaId) {
  const [[row]] = await pool.query(`SELECT * FROM ${TABLES.media} WHERE id = ? AND store_id = ?`, [mediaId, storeId]);
  if (!row) return false;
  await pool.query(`DELETE FROM ${TABLES.media} WHERE id = ?`, [mediaId]);
  fs.unlink(path.join(storeUploadDir(storeId), row.filename), () => {
    // Best-effort: the DB row (already deleted) is the source of truth for
    // what "exists" as far as the rest of the app is concerned, so a
    // leftover orphan file on disk (rare — only if this unlink itself
    // fails) isn't user-visible and isn't worth failing the request over.
  });
  return true;
}

module.exports = {
  upload,
  recordUpload,
  listMedia,
  deleteMedia,
  ALLOWED_MIME_TYPES,
  MAX_FILE_SIZE,
  MAX_FILES_PER_UPLOAD,
};
